data.Corefile:
.:53 {
    errors
    health {
        lameduck 10s
    }
    ready
    hosts /etc/coredns-static/hosts {
        ttl 30
        fallthrough
    }
    kubernetes cluster.local in-addr.arpa ip6.arpa {
        pods insecure
        fallthrough in-addr.arpa ip6.arpa
        ttl 30
    }
    autopath @kubernetes
    prometheus 0.0.0.0:9153
    forward . /etc/resolv.conf
    cache 30
    loop
    reload
    loadbalance
}
